import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 23 剥：基础被侵蚀时先保其所依至读后比较与自测","description":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","frontmatter":{"title":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 23 剥：基础被侵蚀时先保其所依至读后比较与自测","description":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","splitFrom":"life/personal/yijing/hexagrams-17-24.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读三：随蛊临观至噬嗑贲剥复","summary":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称","link":"/life/personal/yijing/hexagrams-17-24-part-02"},"next":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","link":"/life/personal/yijing/hexagrams-25-32"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称","link":"/life/personal/yijing/hexagrams-17-24-part-02"},"next":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","link":"/life/personal/yijing/hexagrams-25-32"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-17-24-part-03.md","filePath":"life/personal/yijing/hexagrams-17-24-part-03.md"}'),i={name:"life/personal/yijing/hexagrams-17-24-part-03.md"};function o(s,t,l,d,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读三-随蛊临观至噬嗑贲剥复-·-23-剥-基础被侵蚀时先保其所依至读后比较与自测" tabindex="-1">六十四卦详读三：随蛊临观至噬嗑贲剥复 · 23 剥：基础被侵蚀时先保其所依至读后比较与自测 <a class="header-anchor" href="#六十四卦详读三-随蛊临观至噬嗑贲剥复-·-23-剥-基础被侵蚀时先保其所依至读后比较与自测" aria-label="Permalink to &quot;六十四卦详读三：随蛊临观至噬嗑贲剥复 · 23 剥：基础被侵蚀时先保其所依至读后比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-17-24">返回分篇目录</a></p><p>本组把注意力从个人进退转向关系如何形成、积弊如何修复、治理如何实施。随与蛊可比较顺从与整治，临与观可比较接近与审视，噬嗑与贲可比较强制裁断与文明表达，剥与复则讨论基础损耗和初步恢复。</p><p>本文实际对读维基文库《周易》各卦与《周易正义》卷三对应篇。引文为古籍文字，简体说明为本篇概括；用字有异处参考《正义》，例如噬嗑“臘肉”、剥“君子得輿”。《周易》单卦网页有时断句不同，剥卦辞按《正义》读为“不利有攸往”。这些整理不构成古本校勘结论，重要疑义另行标注。涉及日期、刑罚、王侯和祭祀时，应保留历史语境，不将其直接变成预测或今日行为规范。</p><h2 id="gua-23" tabindex="-1">23 剥：基础被侵蚀时先保其所依 <a class="header-anchor" href="#gua-23" aria-label="Permalink to &quot;23 剥：基础被侵蚀时先保其所依 {#gua-23}&quot;">​</a></h2><p><strong>卦符：䷖　上卦：艮 ☶（山）　下卦：坤 ☷（地）。</strong></p><p><strong>卦辞原文</strong>：剝：不利有攸往。</p><p><strong>白话概括</strong>：阴长而阳逐步剥落，是传统卦象解释；在人事中可观察为支撑层层受损。《正义》强调顺时而止，不以强亢触忤而徒然损身。这里不是说面对破坏永远不抵抗，而是先看局势与剩余支点，不能把继续向前当成唯一勇敢的选择。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：剝牀以足，蔑貞凶。</td><td>床足先受损，整体支撑开始动摇。根基问题尚不显眼，却不能因暂时还能使用便忽略。</td></tr><tr><td>六二：剝牀以辨，蔑貞凶。</td><td>侵蚀进一步到床的分界、床身部件；辨的具体所指有异说。损害在扩展，不能只修表面。</td></tr><tr><td>六三：剝之，无咎。</td><td>在剥落环境中有不同选择，古注以与上九相应、不随群阴为释。处在群体之中不必认同全部行为。</td></tr><tr><td>六四：剝牀以膚，凶。</td><td>损害已经贴近身体，危险迫切。床足、辨、肤构成逐步逼近的叙述。</td></tr><tr><td>六五：貫魚，以宮人寵，无不利。</td><td>以贯鱼和宫人依序受宠为象，古注解释为统率众阴、使其有序。它保留宫廷等级与性别制度，不应移为现代关系规范。</td></tr><tr><td>上九：碩果不食，君子得輿，小人剝廬。</td><td>尚有大果未食，保留再生之种；君子得承载，小人则继续毁坏庇身之所。同一终局仍有不同用法。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“山附地上，剝；上以厚下，安宅。”</p><p><strong>解释</strong>：山依大地而立，居上者要安稳，须先使下层基础厚实。这不是单向要求在下者忍耐，反而把责任指向依赖其支撑的上位者。</p><p><strong>整体读法与误区</strong>：剥的价值在于帮助看见系统性侵蚀：不是只责怪最后一块倒下的木板。上九的硕果又提示保留种子、人才、知识与恢复能力的重要，但这些只是现代类比，不是原文逐项列举。与<a href="/life/personal/yijing/hexagrams-17-24-part-03#gua-24">复卦</a>对读，须把“尚存恢复条件”与“必定马上恢复”分开。</p><p><strong>细读线索</strong>：剥只有最上一爻为阳，五阴在下增长，这是古注谈剥落的卦体背景。床足先坏而身尚未受伤，六四才切近肤，时间上的延迟容易使问题被低估。六三无咎、六五无不利又说明阴爻并不能一概等同为道德恶人，它们仍有不同作为。读剥时若只把阴阳翻译为好人与坏人，就会解释不了这些爻，也会失去经文对处境、选择和结构变化的区分。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D" target="_blank" rel="noopener noreferrer">《周易·剥》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E5%89%9D" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·剥》</a>。</p><h2 id="gua-24" tabindex="-1">24 复：回转之初，贵在及时与养护 <a class="header-anchor" href="#gua-24" aria-label="Permalink to &quot;24 复：回转之初，贵在及时与养护 {#gua-24}&quot;">​</a></h2><p><strong>卦符：䷗　上卦：坤 ☷（地）　下卦：震 ☳（雷、动）。</strong></p><p><strong>卦辞原文</strong>：復：亨。出入无疾，朋來无咎。反復其道，七日來復，利有攸往。</p><p><strong>白话概括</strong>：一阳回到最下，恢复刚刚开始。古传借阴阳往复说明回转，王、孔注疏又结合卦气解释七日；此类时间说法有学术分歧，不可读成任何困境七天自动恢复。复既可指自然往复，也被《小象》展开为修身改过，二者有关联但不是同一层面的事实。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：不遠復，无祇悔，元吉。</td><td>偏离不远便回转，不让悔恨加深。祇、祗等字有异文，核心是及时修正。</td></tr><tr><td>六二：休復，吉。</td><td>以美善、从容的方式回转；古注联系亲近初九之仁，说明修正可以得到他人的帮助。</td></tr><tr><td>六三：頻復，厲无咎。</td><td>屡次失而复返，虽有危险，愿意返回仍不应简单归咎。无咎不等于反复失误没有成本。</td></tr><tr><td>六四：中行獨復。</td><td>在众人之间独自回转，从道而不盲从。经文没有直接标吉凶，不应替它添上确定结果。</td></tr><tr><td>六五：敦復，无悔。</td><td>深厚、诚实地反省而复，不止于口头承认。回转能否稳定，取决于实际持续。</td></tr><tr><td>上六：迷復，凶，有災眚。用行師，終有大敗，以其國君，凶；至于十年，不克征。</td><td>迷失而不知回返，若再兴师行动，将扩大灾害。十年是严重久困的叙述，不应套成个人运势年限。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“雷在地中，復；先王以至日閉關，商旅不行，后不省方。”</p><p><strong>解释</strong>：冬至一阳初复，古代以闭关、停行来养护初生之气。这是古代礼制与宇宙观的结合；思想重点在恢复之初需要保护，不是要求今日社会照搬全面停运。</p><p><strong>整体读法与误区</strong>：复最重视“多早回来、如何回来”。初九不远，六三频复，六五敦复，上六迷复，构成不同回转质量。卦辞利往而大象主静，看似相反，实则提醒增长方向与当前养护措施可以不同。现代反思可关照纠错与休整，但不能用“周期必回”否定损失和现实干预。</p><p><strong>细读线索</strong>：复的一阳在初，与剥的一阳在上形成鲜明对照：同样数量很少，位置改变便使它成为生长的起点。六四独复位于群阴之间，古注强调其与初九相应，说明独并不必然等于完全没有支援。六三频复则承认修正可以反复发生。把初阳看作需要养护的微小可能，便能理解大象为何闭关，也能理解为什么初步改善不应立刻承担全部恢复任务。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9" target="_blank" rel="noopener noreferrer">《周易·复》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E5%BE%A9" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·复》</a>。</p><h2 id="读后比较与自测" tabindex="-1">读后比较与自测 <a class="header-anchor" href="#读后比较与自测" aria-label="Permalink to &quot;读后比较与自测 {#读后比较与自测}&quot;">​</a></h2><ol><li>随为什么需要“利贞”限制？蛊六四为什么不能只求宽缓？</li><li>临的甘临与观的窥观，分别暴露什么信息与关系问题？</li><li>噬嗑可以“利用狱”，贲却“无敢折狱”，两种条件为什么不能混用？</li><li>剥的大象为什么把“厚下”作为安宅之道？这与只要求下层忍耐有何不同？</li><li>复卦的七日、上六的十年，应如何与真实日期预测区分？“频复”与“迷复”的差别又在哪里？</li></ol><p>前篇：<a href="/life/personal/yijing/hexagrams-09-16">第 09—16 卦：小畜至豫</a>。后篇：<a href="/life/personal/yijing/hexagrams-25-32">第 25—32 卦：无妄大畜至咸恒</a>。返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',27)])])}const f=e(i,[["render",o]]);export{c as __pageData,f as default};
